message.content:
{
  "title": "The Glass Diver's Rescue",
  "gate_token": "aUuEO1xyGIykdrq2JVpipw",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a shattered mirror map in the ruins.",
      "visual_description": "A broken courtyard with cracked flagstones, an ornate mirror frame leaning against a wall, and Mara tracing ink lines on a torn map with a brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver arrives through a window portal.",
      "visual_description": "A shimmering glass-like surface in an archway ripples, and the Glass Diver steps through, helmet reflecting the ruined city skyline.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "In a dim stone chamber, the Oracle Lamp flickers atop a pedestal, its single eye glowing as it speaks to Mara and the Glass Diver.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The Tin Fox scouts the castle gate path.",
      "visual_description": "A rusted iron gate with broken hinges, overgrown with thorny vines; the Tin Fox scurries ahead, its blue eyes scanning, tail ticking.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The Sleeping Tax Collector blocks a passage.",
      "visual_description": "A narrow corridor with a desk and stool, the Sleeping Tax Collector slumped over, papers stuck to sleeves, ledger as pillow.",
      "characters": ["sleeping_tax_collector", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara navigates through the old royal banners.",
      "visual_description": "A long hall hung with faded banners bearing worn crests, wind blowing through broken windows, Mara checking compass against map.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp reveals a trap in the next courtyard.",
      "visual_description": "A sunken courtyard with crumbling statues, shadows pooling in corners; the Oracle Lamp's flame dims and brightens in warning.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The Glass Diver swims through a magic door.",
      "visual_description": "A stone doorframe filled with liquid light, the Glass Diver diving into it, coat reflecting fragments of the room behind.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox disables a pressure plate on the floor.",
      "visual_description": "A tiled floor with a slightly depressed plate, Tin Fox reaching inside its chest with a tiny key to lock the mechanism.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The Sleeping Tax Collector snores through a collapse.",
      "visual_description": "A ceiling partially caved in, dust and rubble around, the Sleeping Tax Collector still asleep on a chair amidst the debris.",
      "characters": ["sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Mara maps a hidden staircase behind a tapestry.",
      "visual_description": "A frayed tapestry pulled aside, revealing a spiral stair; Mara marking the route with ink while holding a lantern.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Glass Diver retrieves a key from a mirrored pool.",
      "visual_description": "A shallow reflecting pool in a garden, the Glass Diver submerged up to shoulders, reaching for a brass key at the bottom.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The Oracle Lamp warns of armored patrols nearby.",
      "visual_description": "A narrow alley between ruined buildings, the Oracle Lamp held high, its eye scanning as footsteps echo from around a corner.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox leads the group through a secret passage.",
      "visual_description": "A low tunnel behind a false wall, Tin Fox in front, its blue eyes illuminating cobwebs and loose stones.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Mara confronts a locked magic door with no keyhole.",
      "visual_description": "A smooth stone door etched with glowing runes, Mara pressing her compass against it as the Glass Diver approaches.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The Glass Diver swims through the magic door's surface.",
      "visual_description": "The door's runes flare as the Glass Diver touches it, then passes through as if through water, ripples spreading across the stone.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The group escapes across a crumbling bridge.",
      "visual_description": "A stone bridge over a ravine, missing sections and swaying ropes, the Glass Diver helping Mara across while Tin Fox scurries ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The team reaches safety as the bridge collapses.",
      "visual_description": "The far side of the ravine, the bridge falling into the mist behind them, the Oracle Lamp glowing steadily, the Tin Fox winding its tail.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

